    .hero-visual{position:relative;display:grid;place-items:center;min-height:600px;padding:48px}.hero-visual:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,var(--pine-900),rgba(9,37,29,.22) 34%,rgba(9,37,29,.03)),url("https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1400&q=85") center/cover;opacity:.82}.scan-stage{position:relative;z-index:3;width:min(430px,100%)}.scan-card{position:relative;overflow:hidden;padding:28px;border:1px solid rgba(255,255,255,.14);border-radius:30px;background:rgba(6,26,21,.78);box-shadow:0 38px 100px -40px rgba(0,0,0,.9);backdrop-filter:blur(18px)}.scan-card:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 78% 18%,rgba(223,252,98,.18),transparent 25%),radial-gradient(circle at 14% 86%,rgba(242,123,74,.14),transparent 24%);pointer-events:none}.scan-head{position:relative;display:flex;align-items:center;justify-content:space-between;gap:16px}.scan-head small{display:block;color:rgba(255,255,255,.48);font-size:9px;font-weight:800;letter-spacing:.17em;text-transform:uppercase}.scan-head strong{display:block;margin-top:6px;font-family:"Fraunces",serif;font-size:23px}.scan-status{display:inline-flex;align-items:center;gap:7px;padding:8px 10px;border-radius:999px;background:rgba(223,252,98,.12);color:var(--acid);font-size:9px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}.scan-status i{width:7px;height:7px;border-radius:50%;background:var(--acid)}.scan-window{position:relative;display:grid;place-items:center;aspect-ratio:1.16;margin:24px 0;border:1px solid rgba(255,255,255,.11);border-radius:24px;background:rgba(255,255,255,.045);overflow:hidden}.scan-window:before,.scan-window:after{content:"";position:absolute;width:68px;height:68px;border-color:var(--acid);border-style:solid;opacity:.85}.scan-window:before{left:20px;top:20px;border-width:2px 0 0 2px;border-radius:12px 0 0 0}.scan-window:after{right:20px;bottom:20px;border-width:0