    .section{padding:90px 0}.verify-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(360px,.58fr);gap:28px;align-items:start}.panel{border:1px solid var(--line);border-radius:30px;background:rgba(255,253,246,.76);box-shadow:var(--card-shadow)}.verify-panel{padding:34px}.panel-kicker{margin:0 0 8px;color:var(--pine-700);font-size:10px;font-weight:900;letter-spacing:.15em;text-transform:uppercase}.verify-panel h2,.result-card h2,.how-grid h2{margin:0;font-family:"Fraunces",serif;font-size:clamp(32px,4vw,52px);font-weight:600;letter-spacing:-.05em;line-height:1}.verify-panel h2 em,.how-grid h2 em{color:var(--pine-700);font-style:italic}.lead{max-width:650px;margin:14px 0 0;color:var(--muted);line-height:1.7}.code-wrap{margin-top:28px}.code-label{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:10px}.code-label label{font-size:12px;font-weight:800}.code-label span{color:var(--muted);font-size:10px}.code-field{display:flex;align-items:center;gap:10px;padding:8px;border:1px solid var(--line);border-radius:18px;background:var(--cream);transition:.2s ease}.code-field:focus-within{border-color:rgba(27,82,66,.42);box-shadow:0 0 0 4px rgba(27,82,66,.08)}.code-field input{min-width:0;flex:1;height:48px;padding:0 13px;border:0;outline:0;background:transparent;color:var(--pine-900);font-size:17px;font-weight:800;letter-spacing:.13em;text-transform:uppercase}.code-field button{flex:0 0 auto}.btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:48px;padding:0 18px;border:1px solid transparent;border-radius:15px;font-size:13px;font-weight:800;transition:.22s ease}.btn-primary{background:var(--acid);color:var(--pine-950)}.btn-primary:hover{transform:translateY(-2px);box-shadow:0 18px 46px -24px rgba(223,252,98,.62)}.btn-dark{background:var(--pine-900);color:#fff}.btn-soft{border-color:var(--line);background:rgba(255,253,246,.76);color:var(--pine-900)}.btn-ghost{border-color:rgba(255,255,255,.17);backgroun