    .mini-aside{position:sticky;top:104px;overflow:hidden;padding:28px;background:var(--pine-900);color:#fff}.mini-aside:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 82% 15%,rgba(223,252,98,.15),transparent 25%),radial-gradient(circle at 10% 90%,rgba(242,123,74,.12),transparent 25%)}.mini-aside>*{position:relative}.mini-aside h3{margin:0;font-family:"Fraunces",serif;font-size:28px;font-weight:600;letter-spacing:-.04em}.mini-aside p{margin:10px 0 0;color:rgba(255,255,255,.59);font-size:12px;line-height:1.65}.aside-list{display:grid;gap:12px;margin-top:24px}.aside-row{display:flex;align-items:flex-start;gap:11px;padding-top:12px;border-top:1px solid rgba(255,255,255,.09)}.aside-row:first-child{padding-top:0;border-top:0}.aside-row span{display:grid;place-items:center;width:30px;height:30px;flex:0 0 auto;border-radius:11px;background:rgba(223,252,98,.1);color:var(--acid)}.aside-row strong{display:block;font-size:12px}.aside-row small{display:block;margin-top:3px;color:rgba(255,255,255,.47);font-size:10px;line-height:1.45}
    .result-wrap{margin-top:28px}.state-card{overflow:hidden;border:1px solid var(--line);border-radius:28px;background:var(--cream);box-shadow:var(--card-shadow)}.state-top{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:20px 24px;border-bottom:1px solid var(--line)}.state-badge{display:inline-flex;align-items:center;gap:8px;padding:8px 10px;border-radius:999px;font-size:9px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}.state-badge i{width:7px;height:7px;border-radius:50%}.state-badge.valid{background:rgba(27,82,66,.11);color:var(--pine-700)}.state-badge.valid i{background:var(--pine-700)}.state-badge.used{background:rgba(217,153,46,.13);color:#9a6719}.state-badge.used i{background:var(--warning)}.state-badge.invalid{background:rgba(204,77,61,.12);color:#a63d31}.state-badge.invalid i{background:var(--danger)}.state-code{color:var(--muted);font-size:10px;font-weight:800;letter-spacing:.1em}.state-body{padding:26px}.valid-layout{display:grid;grid-template-columns:minmax(0,.78fr) minmax(300px,.54fr);gap:20px}.balance-card{position:relative;overflow:hidden;min-height:260px;padding:26px;border-radius:24px;background:linear-gradient(145deg,#173e32,#0a261e 70%);color:#fff}.balance-card:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 82% 18%,rgba(223,252,98,.2),transparent 23%),url("data:image/svg+xml,%3Csvg width='560' height='360' viewBox='0 0 560 360' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' stroke='%23fff' stroke-opacity='.075'%3E%3Cpath d='M-20 230c86-110 189-115 261-31 68 79 132 73 210 4 70-61 128-48 170 4'/%3E%3Cpath d='M-28 263c93-109 200-108 276-25 70 76 137 67 213-1 67-59 126-47 165-9'/%3E%3Cpath d='M-35 297c103-108 211-98 289-19 73 72 141 59 215-6 64-57 122-47 160-18'/%3E%3C/g%3E%3C/svg%3E") center/cover}.balance-card>*{position:relative}.balance-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.balance-head strong{font-family:"Fraunces",s