    .section-head{display:flex;align-items:end;justify-content:space-between;gap:28px;margin-bottom:28px}.section-head h2{max-width:760px;margin:0;font-family:"Fraunces",serif;font-size:clamp(36px,5vw,64px);font-weight:600;letter-spacing:-.055em;line-height:.98}.section-head h2 em{color:var(--pine-700);font-style:italic}.section-head p{max-width:500px;margin:0;color:var(--muted);font-size:13px;line-height:1.7}.how-grid{display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,1.3fr);gap:28px;align-items:start}.steps{display:grid;gap:12px}.how-step{display:grid;grid-template-columns:44px minmax(0,1fr);gap:14px;padding:18px;border:1px solid var(--line);border-radius:18px;background:rgba(255,253,246,.7)}.how-step>span{display:grid;place-items:center;width:44px;height:44px;border-radius:15px;background:var(--pine-900);color:var(--acid);font-family:"Fraunces",serif;font-size:18px}.how-step strong{display:block;font-size:13px}.how-step p{margin:5px 0 0;color:var(--muted);font-size:11px;line-height:1.55}.use-cases{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.use-card{position:relative;overflow:hidden;min-height:230px;padding:22px;border-radius:24px;background:var(--pine-900);color:#fff}.use-card:nth-child(2){background:#173e32}.use-card:nth-child(3){background:#7d4633}.use-card:nth-child(4){background:#477c75}.use-card:before{content:"";position:absolute;right:-40px;bottom:-70px;width:190px;height:190px;border:1px solid rgba(255,255,255,.1);border-radius:50%;box-shadow:0 0 0 32px rgba(255,255,255,.025)}.use-card>*{position:relative}.use-card small{color:var(--acid);font-size:9px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}.use-card h3{max-width:280px;margin:10px 0 0;font-family:"Fraunces",serif;font-size:25px;font-weight:600;letter-spacing:-.04em;line-height:1.04}.use-card p{max-width:320px;margin:10px 0 0;color:rgba(255,255,255,.58);font-size:11px;line-height:1.6}.use-card a{display:inline-flex;align-items:center;gap:7px;margin-top:22px;color:#fff;font-size:11px;font-weight:800}
    .faq-grid{display:grid;grid-template-columns:minmax(0,.62fr) minmax(0,1fr);gap:46px;align-items:start}.faq-intro h2{margin:0;font-family:"Fraunces",serif;font-size:clamp(36px,5vw,62px);font-weight:600;letter-spacing:-.055em;line-height:1}.faq-intro h2 em{color:var(--pine-700);font-style:italic}.faq-intro p:last-child{max-width:430px;color:var(--muted);font-size:12px;line-height:1.65}.faq-list{display:grid;gap:10px}.faq-item{overflow:hidden;border:1px solid var(--line);border-radius:18px;background:rgba(255,253,246,.74)}.faq-q{display:flex;align-items:center;justify-content:space-between;gap:20px;width:100%;padding:18px;border:0;background:transparent;color:var(--ink);text-align:left;font-size:12px;font-weight:800}.faq-q svg{width:18px;height:18px;flex:0 0 auto;transition:.22s ease}.faq-item.open .faq-q svg{transform:rotate(45deg)}.faq-a{max-height:0;overflow:hidden;transition:max-height .32s ease}.faq-a p{margin:0;padding:0 18px 18px;color:var(--muted);font-size:11px;line-height:1.65}
    .footer{padding:28px 0 100px}.footer-card{display:flex;align-items:flex-start;justify-content:space-between;gap:30px;padding:26px;border-radius:26px;background:var(--pine-950);color:#fff}.footer-card p{max-width:420px;margin:14px 0 0;color:rgba(255,255,255,.46);font-size:11px}.footer-links{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:10px 18px}.footer-links a{color:rgba(255,255,255,.57);font-size:11px}.mobile-menu{position:fixed;inset:0;z-index:100;display:flex;flex-direction:column;padding:18px;background:var(--pine-950);color:#fff;transform:translateX(100%);transition:.28s ease}.mobile-menu.open{transform:none}.mobile-menu-head{display:flex;align-items:center;justify-content:space-between}.mobile-menu-links{display:grid;gap:6px;margin-top:28px}.mobile-menu-links a{padding:15px;border-bottom:1px solid rgba(255,255,255,.08);font-family:"Fraunces",serif;font-size:28px}.toast{position:fixed;right:18px;bottom:18px;z-index:120;max-width:min(360px,calc(100vw - 36px));padding:13px 16px;border-radius:15px;background:var(--pine-950);color:#fff;box-shadow:0 20px 60px -30px #000;font-size:11px;font-weight:700;opacity:0;transform:translateY(16px);pointer-events:none;transition:.22s ease}.toast.show{opacity:1;transform:none}.modal{position:fixed;inset:0;z-index:110;display:grid;place-items:center;padding:18px;background:rgba(6,26,21,.72);backdrop-filter:blur(10px)}.modal-card{width:min(520px,100%);max-height:min(720px,calc(100vh - 36px));overflow:auto;padding:26px;border-radius:28px;background:var(--cream);box-shadow:0 40px 120px -35px #000}.modal-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}.modal-head h3{margin:0;font-family:"Fraunces",serif;font-size:30px}.close-btn{display:grid;place-items:center;width:38px;height:38px;border:1px solid var(--line);border-radius:13px;background:#fff;color:var(--pine-900)}.form-grid{display:grid;gap:14px;margin-top:22px}.field label{display:block;margin-bottom:7px;font-size:10px;font-weight:800}.field input,.field select{width:100%;height:48px;padding:0 13px;border:1px solid var(--line);border-radius:14px;background:#fff;outline:0}.field input:focus,.field select:focus{border-color:var(--pine-700);box-shadow:0 0 0 4px rgba(27,82,66,.08)}.check-row{display:flex;align-items:flex-start;gap:10px;padding:13px;border-radius:15px;background:rgba(183,201,163,.14);font-size:11px;line-height:1.5}.check-row input{margin-top:2px}.modal-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:20px}
    @media(max-width:1100px){.main-nav{display:none}.menu-btn{display:grid}.hero{grid-template-columns:1fr}.hero-visual{min-height:500px}.verify-grid,.how-grid,.faq-grid{grid-template-columns:1fr}.mini-aside{position:relative;top:auto}.valid-layout{grid-template-columns:1fr}.how-grid{gap:34px}}
    @media(max-width:720px){.shell{width:min(100% - 20px,1460px)}.site-header{padding:8px 0}.nav{gap:8px;padding:8px 8px 8px 11px;border-radius:18px}.brand-mark{width:38px;height:38px;border-radius:13px}.brand-copy strong{font-size:16px}.brand-copy span{display:none}.ticket-cta{min-height:38px;padding:0 12px}.nav-actions{margin-left:auto}.hero{min-height:auto;border-radius:28px}.hero-copy{padding:42px 22px 32px}.hero h1{font-size:clamp(44px,14vw,64px)}.hero-copy>p{font-size:14px}.hero-note{gap:11px 16px}.hero-visual{min-height:420px;padding:26px 18px 42px}.scan-card{padding:20px;border-radius:24px}.scan-window{margin:18px 0}.scan-foot{align-items:flex-start;flex-direction:column}.demo-code{white-space:normal}.section{padding:64px 0}.verify-panel{padding:22px}.code-field{align-items:stretch;flex-direction:column;padding:7px}.code-field input{width:100%;height:52px;text-align:center;font-size:15px}.code-field .btn{width:100%}.quick-codes{overflow:auto;flex-wrap:nowrap;padding-bottom:4px}.quick-codes button{flex:0 0 auto}.state-top{align-items:flex-start;flex-direction:column;padding:18px}.state-body{padding:18px}.balance-card{min-height:240px;padding:22px}.balance-main strong{font-size:48px}.balance-foot{align-items:flex-start;flex-direction:column}.result-actions{display:grid;grid-template-columns:1fr}.result-actions .btn{width:100%}.section-head{align-items:flex-start;flex-direction:column}.use-cases{grid-template-columns:1fr}.footer-card{align-items:flex-start;flex-direction:column}.footer-links{justify-content:flex-start}.modal{align-items:end;padding:0}.modal-card{width:100%;max-height:88vh;border-radius:28px 28px 0 0;padding:22px}.modal-actions{display:grid;grid-template-columns:1fr}.modal-actions .btn{width:100%}.toast{right:10px;bottom:10px}.faq-grid{gap:28px}}
    @media(max-width:390px){.ticket-cta{font-size:12px;padding:0 10px}.menu-btn{width:38px;height:38px}.hero-copy{padding-inline:18px}.scan-stage{width:100%}.qr-demo{width:132px;height:132px}.verify-panel h2{font-size:34px}.state-code{word-break:break-all}.detail-row{align-items:flex-start;flex-direction:column}.detail-row strong{text-align:left}}
    @media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}
  </style>
</head>
<body x-data="voucherVerifyPage()" x-init="init()">
<header class="site-header">
  <div class="shell nav">
    <a class="brand" href="/"><span class="brand-mark"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m4 17 5-10 3 6 2-4 6 8"/><path d="M3 20h18"/></svg></span><span class="brand-copy"><strong>Nordvale</strong><span>Wild Park & Forest Reserve</span></span></a>
    <nav class="main-nav"><a href="/experiente">Experiențe</a><a href="/planifica">Planifică vizita</a><a href="/calendar">Calendar</a><a href="/card-cadou">Cadouri</a></nav>
    <div class="nav-actions"><a class="ticket-cta" href="/bilete">Bilete</a><button class="menu-btn" type="button" @click="menuOpen=true" aria-label="Deschide meniul"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 7h16M4 12h16M4 17h16"/></svg></button></div>
  </div>
</header>
<main>
  <section class="shell hero topo">
    <div class="hero-copy"><span class="eyebrow"><i></i>Voucher Nordvale</span><h1>Verifică soldul. Activează <em>aventura.</em></h1><p>Introdu codul de pe voucher pentru a vedea valoarea disponibilă, valabilitatea și opțiunile de utilizare. Poți să îl adaugi în cont sau să îl aplici direct unei rezervări.</p><div class="hero-note"><span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 3 4 6v6c0 5 3.5 8 8 9 4.5-1 8-4 8-9V6z"/><path d="m9 12 2 2 4-5"/></svg>Verificare securizată</span><span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>Sold actualizat instant</span><span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M6 4h12v16H6z"/><path d="M9 8h6M9 12h4"/></svg>Utilizare online</span></div></div>
    <div class="hero-visual"><div class="scan-stage"><div class="scan-card"><div class="scan-head"><div><small>Nordvale Secure Check</small><strong>Voucher scanner</strong></div><span class="scan-status"><i></i>Online</span></div><div class="scan-window"><div class="qr-demo"><template x-for="i in 81" :key="i"><span></span></template></div><div class="scan-line"></div></div><div class="scan-foot"><p>Ai un voucher tipărit? Scanează codul QR sau introdu manual codul de 12 caractere.</p><button class="demo-code" type="button" @click="useCode('NORD-7K4M-2PX9')">Testează NORD-7K4M-2PX9</button></div></div></div></div>
  </section>

  <section class="section" id="verify">
    <div class="shell verify-grid">
      <div class="panel verify-panel">
        <p class="panel-kicker">Verificare voucher</p><h2>Introdu codul de pe <em>card.</em></h2><p class="lead">Codul se găsește în emailul voucherului, în PDF sau pe verso-ul cardului tipărit.</p>
        <form class="code-wrap" @submit.prevent="verifyVoucher()">
          <div class="code-label"><label for="voucher-code">Cod voucher</label><span>Exemplu: NORD-7K4M-2PX9</span></div>
          <div class="code-field"><input id="voucher-code" x-model="code" @input="formatCode()" maxlength="14" autocomplete="off" inputmode="text" placeholder="NORD-XXXX-XXXX" aria-describedby="code-help"><button class="btn btn-dark" type="submit" :disabled="loading"><span x-show="!loading">Verifică voucherul</span><span x-show="loading" x-cloak>Se verifică...</span></button></div>
          <div class="quick-codes" id="code-help"><button type="button" @click="useCode('NORD-7K4M-2PX9')">Voucher valid</button><button type="button" @click="useCode('NORD-USED-2408')">Voucher utilizat</button><button type="button" @click="useCode('NORD-EXP-2025')">Voucher expirat</button><button type="button" @click="useCode('NORD-WRONG-000')">Cod invalid</button></div>
        </form>
        <div class="privacy-note"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="5" y="10" width="14" height="10" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg><span>Verificarea nu consumă și nu activează voucherul. Codul este procesat doar pentru afișarea soldului și a stării curente.</span></div>

        <div class="result-wrap" x-show="result" x-cloak>
          <article class="state-card" x-show="result==='valid'">
            <div class="state-top"><span class="state-badge valid"><i></i>Voucher activ</span><span class="state-code" x-text="verifiedCode"></span></div>
            <div class="state-body"><div class="valid-layout"><div class="balance-card"><div class="balance-head"><div><strong>Nordvale Gift Pass</strong><small>Voucher valoric</small></div><svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m4 17 5-10 3 6 2-4 6 8"/><path d="M3 20h18"/></svg></div><div class="balance-main"><span>Sold disponibil</span><strong x-text="vBalance">350 RON</strong></div><div class="balance-foot"><p>Emis pentru <strong x-text="vHolder">Mara D.</strong><br>Valabil până la 29 iulie 2027</p><code>NORD-7K4M-2PX9</code></div></div><div><div class="detail-stack"><div class="detail-row"><span>Valoare inițială</span><strong x-text="vInitial">500 RON</strong></div><div class="detail-row"><span>Utilizat anterior</span><strong x-text="vUsed">150 RON</strong></div><div class="detail-row"><span>Tip</span><strong>Voucher valoric</strong></div><div class="detail-row"><span>Activare</span><strong>Nu este necesară</strong></div></div><div class="use-box"><strong>Poate fi folosit imediat</strong><p>Aplică voucherul într-o rezervare nouă sau salvează-l în cont pentru utilizare ulterioară.</p></div></div></div><div class="result-actions"><button class="btn btn-dark" type="button" @click="openRedeem=true">Aplică la o rezervare</button><button class="btn btn-soft" type="button" @click="openActivate=true">Salvează în cont</button><button class="btn btn-soft" type="button" @click="copyCode()">Copiază codul</button></div></div>
          </article>
          <article class="state-card" x-show="result==='used'"><div class="state-top"><span class="state-badge used"><i></i>Voucher utilizat</span><span class="state-code" x-text="verifiedCode"></span></div><div class="state-body invalid-layout"><div><span class="invalid-icon" style="background:rgba(217,153,46,.13);color:#9a6719"><svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg></span><h3>Voucherul a fost folosit integral</h3><p>Soldul disponibil este 0 RON. Ultima utilizare a fost înregistrată la 24 august 2026 pentru comanda dummy #NV-2026-2084.</p><div class="result-actions"><a class="btn btn-dark" href="/cont/suport">Contactează suportul</a><button class="btn btn-soft" type="button" @click="resetForm()">Verifică alt cod</button></div></div></div></article>
          <article class="state-card" x-show="result==='expired'"><div class="state-top"><span class="state-badge invalid"><i></i>Voucher expirat</span><span class="state-code" x-text="verifiedCode"></span></div><div class="state-body invalid-layout"><div><span class="invalid-icon"><svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="9"/><path d="M12 7v6M12 17h.01"/></svg></span><h3>Perioada de valabilitate s-a încheiat</h3><p>Voucherul a expirat la 31 decembrie 2025. Trimite o solicitare către echipa Nordvale pentru a verifica dacă este eligibil pentru o prelungire excepțională.</p><div class="result-actions"><a class="btn btn-dark" href="/cont/suport">Solicită verificare</a><button class="btn btn-soft" type="button" @click="resetForm()">Verifică alt cod</button></div></div></div></article>
          <article class="state-card" x-show="result==='invalid'"><div class="state-top"><span class="state-badge invalid"><i></i>Cod nerecunoscut</span><span class="state-code" x-text="verifiedCode"></span></div><div class="state-body invalid-layout"><div><span class="invalid-icon"><svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m6 6 12 12M18 6 6 18"/><circle cx="12" cy="12" r="9"/></svg></span><h3>Nu am găsit acest voucher</h3><p>Verifică literele și cifrele codului. Evită spațiile și asigură-te că voucherul a fost emis de Nordvale.</p><div class="result-actions"><button class="btn btn-dark" type="button" @click="resetForm()">Încearcă din nou</button><a class="btn btn-soft" href="/cont/suport">Am nevoie de ajutor</a></div></div></div></article>
        </div>
      </div>
      <aside class="panel mini-aside topo"><h3>Ce poți face după verificare?</h3><p>Voucherul rămâne în siguranță până când alegi explicit una dintre opțiunile de mai jos.</p><div class="aside-list"><div class="aside-row"><span><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M5 4h14v16H5z"/><path d="M8 8h8M8 12h5"/></svg></span><div><strong>Vezi soldul și valabilitatea</strong><small>Inclusiv utilizările anterioare și eventualele restricții.</small></div></div><div class="aside-row"><span><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 7h16v13H4z"/><path d="M8 4h8v3M8 11h8"/></svg></span><div><strong>Aplică la o rezervare</strong><small>Alegi data și experiențele, iar soldul este dedus în checkout.</small></div></div><div class="aside-row"><span><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="8" r="4"/><path d="M5 20c1-4 4-6 7-6s6 2 7 6"/></svg></span><div><strong>Salvează în cont</strong><small>Voucherul va apărea în portofelul digital Nordvale.</small></div></div><div class="aside-row"><span><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 12h16M12 4v16"/></svg></span><div><strong>Completează diferența</strong><small>Dacă rezervarea costă mai mult, achiți restul online.</small></div></div></div></aside>
    </div>
  </section>

  <section class="section paper-grid"><div class="shell how-grid"><div><p class="panel-kicker">Cum funcționează</p><h2>De la cod la <em>ziua în pădure.</em></h2><p class="lead">Voucherul nu rezervă automat o dată. După verificare, destinatarul își construiește vizita în funcție de disponibilitate.</p><div class="steps"><div class="how-step"><span>01</span><div><strong>Verifici codul</strong><p>Vezi soldul, produsul, valabilitatea și starea voucherului.</p></div></div><div class="how-step"><span>02</span><div><strong>Alegi experiența</strong><p>Selectezi data, participanții și traseele disponibile.</p></div></div><div class="how-step"><span>03</span><div><strong>Aplici voucherul</strong><p>Codul reduce valoarea comenzii; diferența poate fi achitată online.</p></div></div></div></div><div class="use-cases"><article class="use-card"><small>Acces de o zi</small><h3>Transformă soldul într-un Explorer sau Adventure Pass.</h3><p>Voucherul valoric poate acoperi integral sau parțial biletele de acces.</p><a href="/bilete">Vezi biletele →</a></article><article class="use-card"><small>Experiențe</small><h3>Rezervă Canopy Run, Forest Quest sau un tur ghidat.</h3><p>Disponibilitatea se confirmă în calendar înainte de aplicarea voucherului.</p><a href="/experiente">Vezi experiențele →</a></article><article class="use-card"><small>Membership</small><h3>Folosește soldul pentru un abonament Nordvale.</h3><p>Poți completa diferența și activa beneficiile direct în cont.</p><a href="/abonamente">Vezi abonamentele →</a></article><article class="use-card"><small>Cadou nou</small><h3>Ai nevoie de încă un voucher pentru altcineva?</h3><p>Configurează valoarea, mesajul și data livrării din pagina de cadouri.</p><a href="/card-cadou">Creează un voucher →</a></article></div></div></section>

  <section class="section"><div class="shell faq-grid"><div class="faq-intro"><p class="panel-kicker">Întrebări frecvente</p><h2>Codul este simplu. Regulile rămân <em>clare.</em></h2><p>Verificarea nu modifică soldul și nu rezervă automat o vizită.</p></div><div class="faq-list"><template x-for="(faq,i) in faqs" :key="i"><article class="faq-item" :class="openFaq===i?'open':''"><button class="faq-q" type="button" @click="openFaq=openFaq===i?null:i"><span x-text="faq.q"></span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14M5 12h14"/></svg></button><div class="faq-a" :style="openFaq===i?'max-height:190px':''"><p x-text="faq.a"></p></div></article></template></div></div></section>
</main>
<footer class="footer"><div class="shell footer-card"><div><a class="brand" href="/"><span class="brand-mark"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m4 17 5-10 3 6 2-4 6 8"/><path d="M3 20h18"/></svg></span><span class="brand-copy"><strong>Nordvale</strong><span>Wild Park & Forest Reserve</span></span></a><p>Concept dummy pentru un tenant leisure Tixello.</p></div><nav class="footer-links"><a href="/card-cadou">Cumpără voucher</a><a href="/bilete">Bilete</a><a href="/cont/suport">Suport</a><a href="#">Termeni voucher</a></nav></div></footer>
<div class="mobile-menu" :class="menuOpen?'open':''" x-cloak><div class="mobile-menu-head"><a class="brand" href="/"><span class="brand-mark"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m4 17 5-10 3 6 2-4 6 8"/><path d="M3 20h18"/></svg></span><span class="brand-copy"><strong>Nordvale</strong><span>Wild Park & Forest Reserve</span></span></a><button class="menu-btn" style="display:grid" type="button" @click="menuOpen=false" aria-label="Închide meniul"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><div class="mobile-menu-links"><a href="/experiente">Experiențe</a><a href="/planifica">Planifică vizita</a><a href="/calendar">Calendar</a><a href="/card-cadou">Voucher cadou</a><a href="/autentificare">Contul meu</a></div></div>
<div class="modal" x-show="openActivate" x-cloak @keydown.escape.window="openActivate=false"><div class="modal-card" @click.outside="openActivate=false"><div class="modal-head"><div><p class="panel-kicker">Portofel digital</p><h3>Salvează voucherul în cont</h3></div><button class="close-btn" type="button" @click="openActivate=false" aria-label="Închide"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><form class="form-grid" @submit.prevent="activateVoucher()"><div class="field"><label for="activate-email">Email cont Nordvale</label><input id="activate-email" type="email" x-model="accountEmail" placeholder="email@exemplu.ro" required></div><div class="field"><label for="activate-password">Parolă</label><input id="activate-password" type="password" x-model="accountPassword" placeholder="••••••••" required></div><label class="check-row"><input type="checkbox" x-model="acceptAttach" required><span>Confirm că doresc să asociez voucherul <strong x-text="verifiedCode"></strong> acestui cont.</span></label><div class="modal-actions"><button class="btn btn-soft" type="button" @click="openActivate=false">Anulează</button><button class="btn btn-dark" type="submit">Salvează în cont</button></div></form></div></div>
<div class="modal" x-show="openRedeem" x-cloak @keydown.escape.window="openRedeem=false"><div class="modal-card" @click.outside="openRedeem=false"><div class="modal-head"><div><p class="panel-kicker">Folosește voucherul</p><h3>Alege unde continui</h3></div><button class="close-btn" type="button" @click="openRedeem=false" aria-label="Închide"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><div class="form-grid"><button class="btn btn-dark" type="button" @click="continueTo('/bilete')">Bilete și pachete</button><button class="btn btn-soft" type="button" @click="continueTo('/experiente')">Experiențe rezervabile</button><button class="btn btn-soft" type="button" @click="continueTo('/abonamente')">Abonamente</button><div class="privacy-note" style="margin-top:0"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 7h16v13H4z"/><path d="M8 4h8v3"/></svg><span>Codul voucherului va fi păstrat temporar și aplicat automat în checkout-ul demonstrativ.</span></div></div></div></div>
<div class="toast" :class="toastVisible?'show':''" x-text="toast"></div>
<script>
function voucherVerifyPage(){return{
  menuOpen:false,code:'',verifiedCode:'',loading:false,result:null,openFaq:null,openActivate:false,openRedeem:false,accountEmail:'',accountPassword:'',acceptAttach:false,toast:'',toastVisible:false,
  vBalance:'350 RON',vInitial:'500 RON',vUsed:'150 RON',vHolder:'Mara D.',
  faqs:[
    {q:'Verificarea consumă sau activează voucherul?',a:'Nu. Verificarea afișează doar soldul, valabilitatea și starea. Soldul se modifică numai după finalizarea unei comenzi eligibile.'},
    {q:'Pot folosi doar o parte din valoare?',a:'Da. Soldul rămas rămâne pe același cod până la expirare. În exemplul demonstrativ, voucherul a fost emis cu 500 RON și mai are 350 RON disponibili.'},
    {q:'Ce se întâmplă dacă rezervarea costă mai mult?',a:'Voucherul reduce totalul comenzii, iar diferența poate fi achitată cu una dintre metodele disponibile în checkout.'},
    {q:'Pot asocia voucherul unui cont?',a:'Da. După verificare, îl poți salva în portofelul contului. Asocierea nu consumă soldul și poate fi revocată de suport în situații justificate.'},
    {q:'Codul poate fi transferat altei persoane?',a:'Voucherele valorice sunt transferabile până la prima asociere permanentă sau până la utilizare, conform condițiilor comerciale afișate la cumpărare.'}
  ],
  init(){const params=new URLSearchParams(location.search);const incoming=params.get('code');if(incoming){this.code=incoming;this.$nextTick(()=>this.verifyVoucher())}},
  formatCode(){let raw=this.code.toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,12);let parts=[];if(raw.length>0)parts.push(raw.slice(0,4));if(raw.length>4)parts.push(raw.slice(4,8));if(raw.length>8)parts.push(raw.slice(8,12));this.code=parts.join('-')},
  useCode(value){this.code=value;this.verifyVoucher();document.getElementById('verify')?.scrollIntoView({behavior:'smooth',block:'start'})},
  async verifyVoucher(){const normalized=this.code.trim().toUpperCase();if(normalized.length<10){this.showToast('Introdu un cod complet de voucher.');return}this.loading=true;this.result=null;this.verifiedCode=normalized;
    // Coduri demo (showcase offline) — comportament instant, fără apel de rețea.
    const demo=(normalized==='NORD-7K4M-2PX9')?'valid':normalized.includes('USED')?'used':normalized.includes('EXP')?'expired':(normalized.includes('WRONG')||normalized.includes('000'))?'invalid':null;
    if(demo){setTimeout(()=>{this.result=demo;this.loading=false;this.afterResult()},650);return;}
    // Cod real → verificare prin proxy (endpoint tenant-client voucher, dacă e disponibil); fallback demo la eșec.
    try{
      const res=await fetch('/api/proxy.php?action=voucher-verify&code='+encodeURIComponent(normalized));
      const data=await res.json().catch(()=>null);
      const v=data&&(data.data||data);
      if(res.ok&&v&&(v.valid||v.status==='active'||v.balance!=null)){
        const fmt=x=>(typeof x==='number'?x.toLocaleString('ro-RO'):x)+' RON';
        if(v.balance!=null)this.vBalance=fmt(v.balance);
        if(v.initial_amount!=null)this.vInitial=fmt(v.initial_amount);
        if(v.used_amount!=null)this.vUsed=fmt(v.used_amount);
        if(v.recipient_name)this.vHolder=v.recipient_name;
        this.result=(v.balance===0||v.status==='used')?'used':(v.status==='expired'?'expired':'valid');
      }else{this.result='invalid';}
    }catch(e){this.result='invalid';}
    this.loading=false;this.afterResult();
  },
  afterResult(){this.$nextTick(()=>document.querySelector('.result-wrap')?.scrollIntoView({behavior:'smooth',block:'center'}))},
  resetForm(){this.code='';this.verifiedCode='';this.result=null;this.$nextTick(()=>document.getElementById('voucher-code')?.focus())},
  copyCode(){navigator.clipboard?.writeText(this.verifiedCode);this.showToast('Codul voucherului a fost copiat.')},
  activateVoucher(){this.openActivate=false;this.showToast('Voucherul a fost salvat în portofelul Nordvale.');this.accountEmail='';this.accountPassword='';this.acceptAttach=false},
  continueTo(url){sessionStorage.setItem('nordvaleVoucher',this.verifiedCode);this.showToast('Voucherul va fi aplicat în pasul de plată.');setTimeout(()=>location.href=url,650)},
  showToast(message){this.toast=message;this.toastVisible=true;clearTimeout(this._timer);this._timer=setTimeout(()=>this.toastVisible=false,2600)}
}}
</script>
</body>
</html>
